import React, { useState, useEffect, useRef } from "react";
import { Container } from "@shared/schema";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import StatusBadge from "@/components/status-badge";
import RouteVisualizer from "@/components/route-visualizer";
import CarrierStatusBadge from "@/components/carrier-status-badge";
import MedlogStatusBadge from "@/components/medlog-status-badge";
import DangerousGoodsFlag from "@/components/dangerous-goods-flag";
import { BLStatus, RouteStep, UserGroup, CarrierStatus, MedlogStatus } from "@/lib/types";

interface ContainerBlockProps {
  container: Container;
  userGroup: UserGroup;
  onNoteChange: (containerId: number, group: 'carrier' | 'medlog', note: string) => void;
  onSelectChange?: (containerId: number, selected: boolean) => void;
  isSelected?: boolean;
}

const ContainerBlock = ({
  container,
  userGroup,
  onNoteChange,
  onSelectChange,
  isSelected = false,
}: ContainerBlockProps) => {
  const isCarrier = userGroup === "carrier";
  const isMedlog = userGroup === "medlog";

  // Use local state for immediate UI updates, sync with container props
  const [carrierNote, setCarrierNote] = useState(container.carrierNote || "");
  const [medlogNote, setMedlogNote] = useState(container.medlogNote || "");

  // Sync with container props when they change
  useEffect(() => {
    setCarrierNote(container.carrierNote || "");
    setMedlogNote(container.medlogNote || "");
  }, [container.id, container.carrierNote, container.medlogNote]); // Added container.id as key

  // Refs for timeouts
  const carrierTimeoutRef = useRef<NodeJS.Timeout>();
  const medlogTimeoutRef = useRef<NodeJS.Timeout>();

  // Handle carrier note change with debounce
  const handleCarrierNoteChange = (value: string) => {
    if (carrierTimeoutRef.current) {
      clearTimeout(carrierTimeoutRef.current);
    }

    carrierTimeoutRef.current = setTimeout(() => {
      onNoteChange(container.id, 'carrier', value);
    }, 1000);
  };

  // Handle medlog note change with debounce
  const handleMedlogNoteChange = (value: string) => {
    if (medlogTimeoutRef.current) {
      clearTimeout(medlogTimeoutRef.current);
    }

    medlogTimeoutRef.current = setTimeout(() => {
      onNoteChange(container.id, 'medlog', value);
    }, 1000);
  };

  // Cleanup timeouts on unmount
  useEffect(() => {
    return () => {
      if (carrierTimeoutRef.current) {
        clearTimeout(carrierTimeoutRef.current);
      }
      if (medlogTimeoutRef.current) {
        clearTimeout(medlogTimeoutRef.current);
      }
    };
  }, []);

  // Check if this container is newly added
  const isNewContainer = container.isNewContainer;

  return (
    <div className={`border border-gray-300 bg-gray-50 rounded-lg px-4 py-3 mb-4 shadow-lg ${
      isNewContainer ? 'border-l-4 border-l-yellow-400 bg-yellow-50' : ''
    }`}>
      {/* First row - Container details */}
      <div className="flex items-center justify-between text-sm font-medium">
        <div className="flex items-center gap-3">
          <Checkbox
            checked={isSelected}
            onCheckedChange={(checked) => onSelectChange?.(container.id, checked as boolean)}
          />
          <span className="font-semibold">{container.jobNumber}</span>
        </div>

        <div className="flex items-center gap-6 flex-1 justify-between ml-4">
          <div className="flex items-center gap-2">
            <div className={`font-mono text-sm ${container.changedFields?.includes('containerNumber') ? 'bg-yellow-100 px-2 py-1 rounded border-l-2 border-yellow-400' : ''}`}>
              {container.containerNumber}
            </div>
            {container.dangerousCargo && <DangerousGoodsFlag />}
          </div>
          <div className={`text-sm ${container.changedFields?.includes('sizeType') ? 'bg-yellow-100 px-2 py-1 rounded border-l-2 border-yellow-400' : ''}`}>
            {container.sizeType}
          </div>
          <div className={`text-sm ${container.changedFields?.includes('dateTime') ? 'bg-yellow-100 px-2 py-1 rounded border-l-2 border-yellow-400' : ''}`}>
            {container.dateTime ? new Date(container.dateTime).toLocaleString('en-US', {
              month: 'short',
              day: 'numeric',
              hour: '2-digit',
              minute: '2-digit'
            }) : 'N/A'}
          </div>
          <div className="flex items-center gap-2">
            <RouteVisualizer currentStep={container.routeStep as RouteStep} />
          </div>
          <div className={`${container.changedFields?.includes('status') ? 'bg-yellow-100 px-2 py-1 rounded border-l-2 border-yellow-400' : ''}`}>
            <StatusBadge status={container.status as BLStatus} />
          </div>
          <div>
            <CarrierStatusBadge status={container.carrierStatus as CarrierStatus} />
          </div>
          <div>
            <MedlogStatusBadge status={container.medlogStatus as MedlogStatus} />
          </div>
          <div className="text-sm font-mono">
            {container.trainName || '-'}
          </div>
          <div className="text-sm">
            {container.trainEtd || '-'}
          </div>
        </div>
      </div>

      {/* Second row - Notes */}
      <div className="flex gap-4 mt-3">
        {/* Carrier Note */}
        <div className="flex items-center w-1/2 gap-2">
          <label className="text-sm font-semibold text-gray-700 whitespace-nowrap">Carrier:</label>
          <div className="relative flex-1">
            <Input
              type="text"
              className={`text-sm ${
                !isCarrier ? "bg-gray-100 text-gray-600" : ""
              }`}
              value={carrierNote}
              onChange={(e) => handleCarrierNoteChange(e.target.value)}
              readOnly={!isCarrier}
              placeholder="Note"
            />
          </div>
        </div>

        {/* Medlog Note */}
        <div className="flex items-center w-1/2 gap-2">
          <label className="text-sm font-semibold text-gray-700 whitespace-nowrap">Medlog:</label>
          <div className="relative flex-1">
            <Input
              type="text"
              className={`text-sm ${
                !isMedlog ? "bg-gray-100 text-gray-600" : ""
              }`}
              value={medlogNote}
              onChange={(e) => handleMedlogNoteChange(e.target.value)}
              readOnly={!isMedlog}
              placeholder="Note"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContainerBlock;

client/src/components/container-list.tsx.content:
import React, { useState } from "react";
import { Container } from "@shared/schema";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import ContainerBlock from "@/components/container-block";
import { UserGroup } from "@/lib/types";
import { useMutation } from "@tanstack/react-query";
import { queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface ContainerListProps {
  data: Container[];
  isLoading?: boolean;
  currentUserGroup?: UserGroup;
}

export default function ContainerList({ data, isLoading, currentUserGroup = 'medlog' }: ContainerListProps) {
  const [selectedRows, setSelectedRows] = useState<Set<number>>(new Set());
  const { toast } = useToast();

  // Mutation for updating container notes
  const updateNoteMutation = useMutation({
    mutationFn: async ({ containerId, group, note }: { containerId: number; group: 'carrier' | 'medlog'; note: string }) => {
      const response = await fetch(`/api/containers/${containerId}/note`, {
        method: 'PATCH',
        body: JSON.stringify({ group, note }),
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) throw new Error('Failed to update note');
      return response.json();
    },
    onSuccess: (_, { containerId }) => {
      // Only show success toast if user explicitly requested it, not on auto-save
      // Invalidate container queries to refresh the data silently
      queryClient.invalidateQueries({ 
        queryKey: ['/api/containers']
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update container note. Please try again.",
        variant: "destructive",
      });
    }
  });

  // Helper function to update container notes
  const handleUpdateContainerNote = (containerId: number, group: 'carrier' | 'medlog', note: string) => {
    updateNoteMutation.mutate({ containerId, group, note });
  };

  const toggleRowSelection = (id: number, selected: boolean) => {
    const newSelected = new Set(selectedRows);
    if (selected) {
      newSelected.add(id);
    } else {
      newSelected.delete(id);
    }
    setSelectedRows(newSelected);
  };

  const toggleAllSelection = () => {
    if (selectedRows.size === data.length) {
      setSelectedRows(new Set());
    } else {
      setSelectedRows(new Set(data.map(container => container.id)));
    }
  };

  if (isLoading) {
    return <div className="p-6 text-center">Loading containers...</div>;
  }

  return (
    <div className="p-4">
      <div className="mb-3 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <h3 className="text-base font-semibold text-gray-900">Container Jobs</h3>
          <div className="flex items-center gap-2">
            <Checkbox
              checked={selectedRows.size === data.length && data.length > 0}
              onCheckedChange={toggleAllSelection}
            />
            <span className="text-sm text-gray-600">Select all</span>
          </div>
        </div>
        <Button className="bg-primary hover:bg-blue-700" size="sm">
          <span className="mr-1">+</span>Add Container
        </Button>
      </div>

      {/* Container blocks */}
      <div>
        {data.length === 0 ? (
          <div className="text-center text-gray-500 py-8">
            No containers found for this booking
          </div>
        ) : (
          data.map((container) => (
            <ContainerBlock
              key={container.id}
              container={container}
              userGroup={currentUserGroup}
              onNoteChange={handleUpdateContainerNote}
              onSelectChange={toggleRowSelection}
              isSelected={selectedRows.has(container.id)}
            />
          ))
        )}
      </div>

      <div className="mt-4 flex justify-end space-x-2">
        <Button variant="outline" size="sm">
          Edit Selected Jobs
        </Button>
        <Button className="bg-primary hover:bg-blue-700" size="sm">
          Update Status
        </Button>
      </div>
    </div>
  );
}

client/src/components/container-notes.ts.content:
import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { UserGroup } from "@/lib/types";

interface ContainerNotesProps {
  carrierNote?: string;
  medlogNote?: string;
  onCarrierNoteChange: (note: string) => void;
  onMedlogNoteChange: (note: string) => void;
  userGroup: UserGroup;
}

const ContainerNotes = ({
  carrierNote = "",
  medlogNote = "",
  onCarrierNoteChange,
  onMedlogNoteChange,
  userGroup,
}: ContainerNotesProps) => {
  const [fullNoteDialog, setFullNoteDialog] = useState<{ type: 'carrier' | 'medlog'; note: string } | null>(null);

  const isCarrier = userGroup === 'carrier';
  const isMedlog = userGroup === 'medlog';

  const isLong = (text: string) => text.length > 80 || text.includes('\n');

  const handleFullNoteClick = (type: 'carrier' | 'medlog', note: string) => {
    setFullNoteDialog({ type, note });
  };

  return (
    <>
      <div className="flex gap-4 items-start pl-8 pt-1 pb-2">
        {/* Carrier Note */}
        <div className="flex items-center w-1/2 gap-2">
          <label className="text-sm font-semibold text-gray-700 whitespace-nowrap">Carrier:</label>
          <div className="relative flex-1">
            <Input
              type="text"
              className={`text-sm ${
                !isCarrier ? "bg-gray-100 text-gray-600" : ""
              }`}
              value={carrierNote}
              onChange={(e) => onCarrierNoteChange(e.target.value)}
              readOnly={!isCarrier}
              placeholder="Note"
            />
            {isLong(carrierNote) && (
              <span
                className="absolute right-2 top-1/2 transform -translate-y-1/2 text-red-500 cursor-pointer hover:text-red-700"
                title="Note is longer than one line - click to view full note"
                onClick={() => handleFullNoteClick('carrier', carrierNote)}
              >
                ↘️
              </span>
            )}
          </div>
        </div>

        {/* Medlog Note */}
        <div className="flex items-center w-1/2 gap-2">
          <label className="text-sm font-semibold text-gray-700 whitespace-nowrap">Medlog:</label>
          <div className="relative flex-1">
            <Input
              type="text"
              className={`text-sm ${
                !isMedlog ? "bg-gray-100 text-gray-600" : ""
              }`}
              value={medlogNote}
              onChange={(e) => onMedlogNoteChange(e.target.value)}
              readOnly={!isMedlog}
              placeholder="Note"
            />
            {isLong(medlogNote) && (
              <span
                className="absolute right-2 top-1/2 transform -translate-y-1/2 text-red-500 cursor-pointer hover:text-red-700"
                title="Note is longer than one line - click to view full note"
                onClick={() => handleFullNoteClick('medlog', medlogNote)}
              >
                ↘️
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Full Note Dialog */}
      <Dialog open={!!fullNoteDialog} onOpenChange={() => setFullNoteDialog(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              {fullNoteDialog?.type === 'carrier' ? 'Carrier' : 'Medlog'} Note - Full View
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <Textarea
              value={fullNoteDialog?.note || ''}
              readOnly
              className="min-h-[120px] resize-none"
            />
            <Button onClick={() => setFullNoteDialog(null)} className="w-full">
              Close
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default ContainerNotes;

